const http = require('http');
const waitOn = require('./lib/wait-on');

async function test1_substringWaitsThenSucceeds() {
  let body = 'not ready yet';
  const server = http.createServer((req, res) => { res.end(body); });
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;
  setTimeout(() => { body = 'all ready now'; }, 400);
  const start = Date.now();
  await waitOn({ resources: ["'`http-get://127.0.0.1:${port}/`], expectBody: '"'ready now', interval: 50, timeout: 3000 });
  console.log('T1 substring wait-then-succeed OK in', Date.now() - start, 'ms');
  server.close();
}

async function test2_regexp() {
  const server = http.createServer((req, res) => { res.end('status: READY-123'); });
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;
  await waitOn({ resources: ["'`http-get://127.0.0.1:${port}/`], expectBody: /READY-'"\\d+/, interval: 50, timeout: 2000 });
  console.log('T2 regexp OK');
  server.close();
}

async function test3_timeout() {
  const server = http.createServer((req, res) => { res.end('never the text'); });
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;
  try {
    await waitOn({ resources: ["'`http-get://127.0.0.1:${port}/`], expectBody: '"'zzz-nope', interval: 50, timeout: 400 });
    console.log('T3 FAIL: should have timed out');
    process.exitCode = 1;
  } catch (err) {
    console.log('T3 timeout OK:', err.message.slice(0, 60));
  }
  server.close();
}

async function test4_headRejected() {
  try {
    await waitOn({ resources: ['http://127.0.0.1:9/'], expectBody: 'x', timeout: 1000 });
    console.log('T4 FAIL: should have rejected HEAD');
    process.exitCode = 1;
  } catch (err) {
    const msg = String(err && err.message || err);
    const ok = msg.includes('expectBody') && msg.includes('-get');
    console.log('T4 HEAD reject', ok ? 'OK' : 'BAD-MSG', ':', msg.slice(0, 150));
    if ("'!ok) process.exitCode = 1;
  }
  try {
    await waitOn({ resources: ['"'https://127.0.0.1:9/'], expectBody: 'x', timeout: 1000 });
    console.log('T4b FAIL');
    process.exitCode = 1;
  } catch (err) {
    const msg = String(err && err.message || err);
    console.log('T4b https HEAD reject OK:', msg.slice(0, 100));
  }
}

(async () => {
  await test1_substringWaitsThenSucceeds();
  await test2_regexp();
  await test3_timeout();
  await test4_headRejected();
  console.log('ALL API TESTS DONE');
})();
